#!/usr/bin/env bash
# Gates compiler-stage self-host substitute contracts.
#
# Heavy parity scripts prove behavior. This smoke proves the self-hosted
# compiler-stage surface itself is wired correctly: each active stage has an
# intent-verification pair, a Makefile target, and fixture/expected files that
# are actually listed by its parity harness.

set -euo pipefail

SCRIPT_PATH="${BASH_SOURCE[0]}"
SCRIPT_DIR="$(cd "${SCRIPT_PATH%/*}" && pwd)"
ROOT_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
SELF_HOST_DIR="$ROOT_DIR/src/self_hosted"
PARITY_DIR="$ROOT_DIR/tests/self_hosted/parity"

fail() {
    echo "[self-host-component-contract] $*" >&2
    exit 1
}

require_file() {
    local rel="$1"
    [[ -f "$ROOT_DIR/$rel" ]] || fail "missing $rel"
}

reject_file() {
    local rel="$1"
    [[ ! -f "$ROOT_DIR/$rel" ]] || fail "$rel must not exist"
}

require_dir() {
    local rel="$1"
    [[ -d "$ROOT_DIR/$rel" ]] || fail "missing directory $rel"
}

TEXT_CACHE_REL=""
TEXT_CACHE_CONTENT=""

load_text_cache() {
    local rel="$1"

    if [[ "$rel" != "$TEXT_CACHE_REL" ]]; then
        [[ -f "$ROOT_DIR/$rel" ]] || fail "missing text input: $rel"
        TEXT_CACHE_CONTENT="$(<"$ROOT_DIR/$rel")" ||
            fail "could not read text input: $rel"
        TEXT_CACHE_REL="$rel"
    fi
}

require_text() {
    local rel="$1"
    local term="$2"
    load_text_cache "$rel"
    [[ "$TEXT_CACHE_CONTENT" == *"$term"* ]] ||
        fail "$rel missing term: $term"
}

require_text_count_at_least() {
    local rel="$1"
    local term="$2"
    local minimum="$3"
    local count

    [[ -f "$ROOT_DIR/$rel" ]] || fail "missing count input: $rel"
    count="$(grep -F -c -- "$term" "$ROOT_DIR/$rel" || true)"
    [[ "$count" -ge "$minimum" ]] ||
        fail "$rel needs at least $minimum occurrence(s) of: $term"
}

require_make_target_text() {
    local target="$1"
    local term="$2"
    local body

    body="$(awk -v target="$target" '
        $0 ~ "^" target ":" { in_target = 1; next }
        in_target && $0 ~ /^[^ \t#][^:]*:/ { exit }
        in_target { print }
    ' "$ROOT_DIR/Makefile")"
    [[ "$body" == *"$term"* ]] ||
        fail "Makefile target $target missing term: $term"
}

reject_text() {
    local rel="$1"
    local term="$2"
    load_text_cache "$rel"
    if [[ "$TEXT_CACHE_CONTENT" == *"$term"* ]]; then
        fail "$rel must not contain retired term: $term"
    fi
}

reject_function_text() {
    local rel="$1"
    local signature="$2"
    local term="$3"
    local body

    [[ -f "$ROOT_DIR/$rel" ]] || fail "missing function input: $rel"
    body="$(awk -v signature="$signature" '
        index($0, signature) == 1 { in_function = 1 }
        in_function && seen && /^func / { exit }
        in_function { print; seen = 1 }
    ' "$ROOT_DIR/$rel")"
    [[ -n "$body" ]] || fail "$rel missing function: $signature"
    [[ "$body" != *"$term"* ]] ||
        fail "$rel function $signature must not contain retired term: $term"
}

reject_regex() {
    local rel="$1"
    local pattern="$2"
    local matches

    [[ -f "$ROOT_DIR/$rel" ]] || fail "missing regex input: $rel"
    matches="$(grep -En "$pattern" "$ROOT_DIR/$rel" || true)"
    [[ -z "$matches" ]] ||
        fail "$rel must not match retired regex: $pattern :: $matches"
}

reject_regex_under() {
    local rel_dir="$1"
    local pattern="$2"
    local matches

    [[ -d "$ROOT_DIR/$rel_dir" ]] || fail "missing regex input directory: $rel_dir"
    matches="$(grep -REn --include='*.pgy' "$pattern" \
        "$ROOT_DIR/$rel_dir" || true)"
    [[ -z "$matches" ]] ||
        fail "$rel_dir must not match retired regex: $pattern :: $matches"
}

require_make_target_recipe_line() {
    local target="$1"
    local recipe_line="$2"

    awk -v target="$target" -v recipe_line="$recipe_line" '
        {
            line = $0
            sub(/\r$/, "", line)
            if (index(line, target ":") == 1) {
                inside = 1
                next
            }
            if (inside && line !~ /^[[:space:]]/ && line ~ /:/) {
                inside = 0
            }
            if (inside && line == "\t" recipe_line) {
                found = 1
            }
        }
        END {
            exit found ? 0 : 1
        }
    ' "$ROOT_DIR/Makefile" ||
        fail "Makefile target $target missing recipe line: $recipe_line"
}

contains_line() {
    local haystack="$1"
    local needle="$2"
    local line

    while IFS= read -r line; do
        [[ "$line" == "$needle" ]] && return 0
    done <<<"$haystack"
    return 1
}

find_stage_owner_sources() {
    local stage="$1"
    local stage_dir="$SELF_HOST_DIR/$stage"
    find "$stage_dir" -type f -name '*.pgy' \
        ! -path "$stage_dir/fixture/*" \
        ! -path "$stage_dir/expected/*" \
        | sort
}

extract_shell_array_items() {
    local file="$1"
    local array_name="$2"
    awk -v array_name="$array_name" '
        $0 ~ "^" array_name "=\\(" { inside = 1; next }
        inside && $0 ~ "^[[:space:]]*\\)" { inside = 0; next }
        inside {
            line = $0
            sub(/[[:space:]]*#.*/, "", line)
            gsub(/"/, "", line)
            gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
            if (line != "") {
                print line
            }
        }
    ' "$file"
}

require_owner_surface() {
    local stage="$1"
    shift
    local stage_dir="$SELF_HOST_DIR/$stage"
    local count
    count="$(find_stage_owner_sources "$stage" | wc -l | tr -d ' ')"
    [[ "$count" -gt 1 ]] ||
        fail "$stage must not be a monolithic main.pgy-only compiler stage"

    local owner
    for owner in "$@"; do
        require_file "src/self_hosted/$stage/$owner"
        require_text "src/self_hosted/$stage/main.pgy" "import \"$owner\";"
    done
}

require_stage_world_binding() {
    local stage="$1"
    local zone="$2"
    local actor="$3"
    local intent="$4"
    local cluster="$5"
    local payload="$6"
    local rel="src/self_hosted/$stage/intent.md"

    require_text "$rel" "## Compiler World Binding"
    require_text "$rel" "- **world_zone**: \`$zone\`"
    require_text "$rel" "- **stage_actor**: \`$actor\`"
    require_text "$rel" "- **stage_intent**: \`$intent\`"
    require_text "$rel" "- **intent_cluster**: \`$cluster\`"
    require_text "$rel" "- **payload_contract**: \`$payload\`"
    require_text "$rel" "- **manifest_binding**: \`$stage|$zone|$actor|$intent|$payload\`"
}

require_max_lines() {
    local rel="$1"
    local cap="$2"
    local count
    [[ -f "$ROOT_DIR/$rel" ]] || fail "missing line-count input: $rel"
    count="$(awk 'END { print NR }' "$ROOT_DIR/$rel")"
    [[ "$count" -le "$cap" ]] ||
        fail "$rel has $count lines; cap is $cap"
}

require_entrypoint_only_main() {
    local stage="$1"
    local rel="src/self_hosted/$stage/main.pgy"
    local path="$ROOT_DIR/$rel"
    local main_funcs
    local other_funcs

    require_max_lines "$rel" 80

    main_funcs="$(grep -Ec '^[[:space:]]*func[[:space:]]+Main[[:space:]]*\(' "$path" || true)"
    [[ "$main_funcs" -eq 1 ]] ||
        fail "$rel must contain exactly one Main entrypoint"

    other_funcs="$(
        grep -En '^[[:space:]]*func[[:space:]]+' "$path" |
            grep -Ev '^[0-9]+:[[:space:]]*func[[:space:]]+Main[[:space:]]*\(' || true
    )"
    [[ -z "$other_funcs" ]] ||
        fail "$rel must not define helper functions: $other_funcs"

    awk '
        /^[[:space:]]*\/\// { next }
        /^[[:space:]]*$/ { next }
        /(^|[[:space:]])(if|while|for)[[:space:]]/ ||
        /ArrayPush[[:space:]]*\(/ ||
        /JsonField/ ||
        /Substring[[:space:]]*\(/ ||
        /String(IndexOf|Length)[[:space:]]*\(/ ||
        /SEMANTIC ERROR/ ||
        /[{]["]/ {
            print FNR ":" $0
        }
    ' "$path" | while IFS= read -r line; do
        fail "$rel reintroduced semantic work into entrypoint: $line"
    done
}

require_stage_owner_line_cap() {
    local stage="$1"
    local file
    local cap
    while IFS= read -r file; do
        rel="${file#"$ROOT_DIR/"}"
        cap=600
        if [[ "$rel" == "src/self_hosted/codegen/emission/stmt_emit.pgy" ]]; then
            cap=640
        fi
        require_max_lines "$rel" "$cap"
        require_text "src/self_hosted/OWNERS.md" "$rel"
    done < <(find_stage_owner_sources "$stage")
}

